// Renders PlantUML through the wasm build of plantuml-core.
// The wasm package is generated by scripts/build-vscode-ext.sh into ./wasm (nodejs target).
'use strict';

const path = require('node:path');

let wasm = null;

function load() {
  if (wasm === null) {
    // Loaded lazily so activation stays cheap and a missing build is reported once.
    wasm = require(path.join(__dirname, '..', 'wasm', 'plantuml_wasm.js'));
  }
  return wasm;
}

/** SVG for a PlantUML source, or an SVG error box when the port rejects it. */
function renderSvg(source) {
  try {
    return { ok: true, svg: load().render(source) };
  } catch (e) {
    return { ok: false, svg: errorSvg(String(e && e.message ? e.message : e)) };
  }
}

function escapeXml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;',
  })[c]);
}

/** The message box the preview shows when a diagram does not render. */
function errorSvg(message) {
  const lines = message.split('\n').slice(0, 4);
  const height = 20 + 16 * lines.length;
  const texts = lines
    .map((l, i) => `<text x="10" y="${20 + 16 * i}" font-family="sans-serif" font-size="12" fill="#b31d28">${escapeXml(l)}</text>`)
    .join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="480" height="${height}">` +
    `<rect width="100%" height="100%" fill="#fff5f5" stroke="#b31d28"/>${texts}</svg>`;
}

module.exports = { renderSvg, errorSvg };
